class Solution:
    def maxProductPair(self, nums: list[int], target: int) -> list[int]:
        best, answer = None, [-1, -1]
        for i in range(len(nums)):
            for j in range(len(nums)):
                if i != j and nums[i] > nums[j] and nums[i] + nums[j] == target:
                    product = nums[i] * nums[j]
                    if best is None or product > best: best, answer = product, [i, j]
        return answer
